            <th colSpan={4} className="border border-blue-600 px-2 py-1.5 text-center">일반TO 배정(안)</th>
            <th colSpan={4} className="border border-blue-600 px-2 py-1.5 text-center">첨단학과신설<br/>특별TO 배정(안)</th>
