   689→import { NextRequest, NextResponse } from 'next/server';
   690→import getDb from '@/lib/db';
   691→
   692→// 화이트리스트: SQL 인젝션 방지
   693→const ALLOWED_FIELDS = new Set([
   694→  'college', 'department', 'confirm_rate_26', 'faculty_count_26',
   695→  'new_hires', 'retirees', 'upcoming_retirements',
   696→  'req_general', 'req_dedicated', 'req_external', 'req_total',
   697→  'invitation_field', 'request_reason',
   698→  'to_general', 'to_dedicated', 'to_external', 'to_total',
   699→  'adv_general', 'adv_dedicated', 'adv_external', 'adv_total',
   700→  'pres_general', 'pres_dedicated', 'pres_external', 'pres_total',
   701→  'assign_reason', 'hq_opinion', 'bigs',
   702→  'to_req_25', 'to_assign_25',
   703→  'hire_regular_25', 'hire_rolling_25', 'hire_total_25',
   704→  'note', 'remark',
   705→]);
   706→
   707→export async function PATCH(
   708→  req: NextRequest,
   709→  { params }: { params: { id: string } }
   710→): Promise<NextResponse> {
   711→  const id = Number(params.id);
   712→  if (!Number.isInteger(id) || id <= 0) {
   713→    return NextResponse.json({ error: '잘못된 ID' }, { status: 400 });
   714→  }
   715→
   716→  let body: Record<string, unknown>;
   717→  try {
   718→    body = await req.json();
   719→  } catch {
   720→    return NextResponse.json({ error: '요청 파싱 실패' }, { status: 400 });
   721→  }
   722→
   723→  const entries = Object.entries(body);
   724→  if (entries.length === 0) {
   725→    return NextResponse.json({ error: '수정할 필드가 없습니다' }, { status: 400 });
   726→  }
   727→
   728→  // 화이트리스트 검증
   729→  for (const [field] of entries) {
   730→    if (!ALLOWED_FIELDS.has(field)) {
   731→      return NextResponse.json({ error: `허용되지 않는 필드: ${field}` }, { status: 400 });
   732→    }
   733→  }
   734→
   735→  const setClauses = entries.map(([field]) => `${field} = ?`).join(', ');
   736→  const values = entries.map(([, val]) => (val === undefined ? null : String(val)));
   737→
   738→  try {
   739→    const db = getDb();
   740→    const result = db
   741→      .prepare(`UPDATE to_haejung SET ${setClauses}, updated_at = datetime('now') WHERE id = ?`)
   742→      .run([...values, id]);
   743→
   744→    if (result.changes === 0) {
   745→      return NextResponse.json({ error: '해당 ID가 없습니다' }, { status: 404 });
   746→    }
   747→    return NextResponse.json({ ok: true });
   748→  } catch (err) {
   749→    return NextResponse.json(
   750→      { error: err instanceof Error ? err.message : '수정 실패' },
   751→      { status: 500 }
   752→    );
   753→  }
   754→}
