    formData.append('file', blob, 'test.csv');
    const req = new NextRequest('http://localhost/api/to-haejung/upload', {
      method: 'POST',
      body: formData,
    });
    const res = await POST(req);
    expect(res.status).toBe(400);
  });

  it('returns 400 for .xlsx extension with wrong MIME type', async () => {
    // 확장자는 .xlsx지만 MIME이 text/plain → 서버는 둘 다 요구하므로 400
    const formData = new FormData();
    const blob = new Blob(['data'], { type: 'text/plain' });
    formData.append('file', blob, 'malicious.xlsx');
    const req = new NextRequest('http://localhost/api/to-haejung/upload', {
      method: 'POST',
      body: formData,
    });
    const res = await POST(req);
    expect(res.status).toBe(400);
  });

  it('returns 400 when required columns are missing', async () => {
    // sheet_to_json이 소속대학/구분 없는 rows 반환
    const xlsx = jest.requireMock('xlsx');
    xlsx.utils.sheet_to_json.mockReturnValueOnce([{ 다른컬럼: '값' }]);
    const req = await makeUploadRequest(Buffer.from('fake-xlsx'));
    const res = await POST(req);
    expect(res.status).toBe(400);
  });

  it('returns 400 when file exceeds 10MB', async () => {
    const bigBuffer = Buffer.alloc(11 * 1024 * 1024); // 11MB
    const req = await makeUploadRequest(bigBuffer);
    const res = await POST(req);
    expect(res.status).toBe(400);
  });

  it('returns 200 and count on valid xlsx', async () => {
    const req = await makeUploadRequest(Buffer.from('fake-xlsx'));
