   686→import { NextRequest, NextResponse } from 'next/server';
   687→import getDb from '@/lib/db';
   688→
   689→// 화이트리스트: SQL 인젝션 방지
   690→const ALLOWED_FIELDS = new Set([
   691→  'college', 'department', 'confirm_rate_26', 'faculty_count_26',
   692→  'new_hires', 'retirees', 'upcoming_retirements',
   693→  'req_general', 'req_dedicated', 'req_external', 'req_total',
   694→  'invitation_field', 'request_reason',
   695→  'to_general', 'to_dedicated', 'to_external', 'to_total',
   696→  'adv_general', 'adv_dedicated', 'adv_external', 'adv_total',
   697→  'pres_general', 'pres_dedicated', 'pres_external', 'pres_total',
   698→  'assign_reason', 'hq_opinion', 'bigs',
   699→  'to_req_25', 'to_assign_25',
   700→  'hire_regular_25', 'hire_rolling_25', 'hire_total_25',
   701→  'note', 'remark',
   702→]);
   703→
   704→export async function PATCH(
   705→  req: NextRequest,
   706→  { params }: { params: { id: string } }
   707→): Promise<NextResponse> {
   708→  const id = Number(params.id);
   709→  if (!Number.isInteger(id) || id <= 0) {
   710→    return NextResponse.json({ error: '잘못된 ID' }, { status: 400 });
   711→  }
   712→
   713→  let body: Record<string, unknown>;
   714→  try {
   715→    body = await req.json();
   716→  } catch {
   717→    return NextResponse.json({ error: '요청 파싱 실패' }, { status: 400 });
   718→  }
   719→
   720→  const entries = Object.entries(body);
   721→  if (entries.length === 0) {
   722→    return NextResponse.json({ error: '수정할 필드가 없습니다' }, { status: 400 });
   723→  }
   724→
   725→  // 화이트리스트 검증
   726→  for (const [field] of entries) {
   727→    if (!ALLOWED_FIELDS.has(field)) {
   728→      return NextResponse.json({ error: `허용되지 않는 필드: ${field}` }, { status: 400 });
   729→    }
   730→  }
   731→
   732→  const setClauses = entries.map(([field]) => `${field} = ?`).join(', ');
   733→  const values = entries.map(([, val]) => (val === undefined ? null : String(val)));
   734→
   735→  try {
   736→    const db = getDb();
   737→    const result = db
   738→      .prepare(`UPDATE to_haejung SET ${setClauses}, updated_at = datetime('now') WHERE id = ?`)
   739→      .run([...values, id]);
   740→
   741→    if (result.changes === 0) {
   742→      return NextResponse.json({ error: '해당 ID가 없습니다' }, { status: 404 });
   743→    }
   744→    return NextResponse.json({ ok: true });
   745→  } catch (err) {
   746→    return NextResponse.json(
   747→      { error: err instanceof Error ? err.message : '수정 실패' },
   748→      { status: 500 }
   749→    );
   750→  }
   751→}
   752→```
