      { 소속대학: '문과대학', 구분: '국어국문학과' },
    ]),
  },
}));

import { POST } from '@/app/api/to-haejung/upload/route';

async function makeUploadRequest(fileBuffer: Buffer, filename = 'test.xlsx', mimeType = 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet') {
  const formData = new FormData();
  const blob = new Blob([fileBuffer], { type: mimeType });
  formData.append('file', blob, filename);
  return new NextRequest('http://localhost/api/to-haejung/upload', {
    method: 'POST',
    body: formData,
  });
}

describe('POST /api/to-haejung/upload', () => {
  beforeEach(() => jest.clearAllMocks());

  it('returns 400 when no file provided', async () => {
    const formData = new FormData();
    const req = new NextRequest('http://localhost/api/to-haejung/upload', {
      method: 'POST',
      body: formData,
    });
    const res = await POST(req);
    expect(res.status).toBe(400);
  });

  it('returns 400 for non-xlsx file', async () => {
    const formData = new FormData();
    const blob = new Blob(['data'], { type: 'text/plain' });
    formData.append('file', blob, 'test.csv');
    const req = new NextRequest('http://localhost/api/to-haejung/upload', {
      method: 'POST',
      body: formData,
    });
    const res = await POST(req);
    expect(res.status).toBe(400);
  });

  it('returns 400 for .xlsx extension with wrong MIME type', async () => {
    const req = await makeUploadRequest(Buffer.from('data'), 'malicious.xlsx', 'text/plain');
    const res = await POST(req);
    expect(res.status).toBe(400);
  });

  it('returns 400 when required columns are missing', async () => {
    const xlsx = jest.requireMock('xlsx');
    xlsx.utils.sheet_to_json.mockReturnValueOnce([{ 다른컬럼: '값' }]);
    const req = await makeUploadRequest(Buffer.from('fake-xlsx'));
    const res = await POST(req);
    expect(res.status).toBe(400);
  });

  it('returns 400 when file exceeds 10MB', async () => {
    const bigBuffer = Buffer.alloc(11 * 1024 * 1024);
    const req = await makeUploadRequest(bigBuffer);
    const res = await POST(req);
    expect(res.status).toBe(400);
